INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT147-S4-Q1$batch04$, 147, 4, 1, $batch04$Paradox$batch04$, $batch04$Cool weather typically weakens muscle power in cold-blooded creatures. In the veiled chameleon, a cold-blooded animal, the speed at which the animal can retract its tongue declines dramatically as the temperature falls. However, the speed at which this chameleon can extend its tongue does not decline much as the temperature falls.$batch04$, $batch04$Which one of the following, if true, most helps to resolve the apparent discrepancy in the information above?$batch04$, $batch04$D$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=147 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT147-S4-Q1$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$Most cold-blooded animals are much more active in warmer weather than in cooler weather.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT147-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$Many cold-blooded animals, including the veiled chameleon, have tongues that can extend quite a distance.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT147-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$Veiled chameleons are found in a wide range of habitats, including ones with wide variations in temperature and ones with moderate climates.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT147-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$In the veiled chameleon, tongue retraction is powered by muscles, whereas tongue extension is driven by energy stored in a rubber band-like sheath.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT147-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$Compared with the muscles in the tongues of most cold-blooded animals, the retraction muscles in the veiled chameleon’s tongue are considerably stronger.$batch04$, $batch04$Irrelevant Comparison$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT147-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT147-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$Cool weather weakens muscle power in cold-blooded animals, and the chameleon's tongue retraction slows sharply in the cold.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$The chameleon's tongue extension barely slows in the cold?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Cold weakens *muscles*. If extension does not depend on muscle power the way retraction does, the cold would not affect it the same way.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a difference between how extension and retraction are powered.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT147-S4-Q1$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Animals being more active in warm weather does not explain why one tongue movement slows and the other does not.$batch04$), ($batch04$B$batch04$, $batch04$How far the tongue extends says nothing about how temperature affects it.$batch04$), ($batch04$C$batch04$, $batch04$Where the chameleons live does not explain the difference between extension and retraction.$batch04$), ($batch04$D$batch04$, $batch04$Retraction runs on muscle, which the cold weakens. Extension runs on energy stored in an elastic sheath, so the cold does not slow it much.$batch04$), ($batch04$E$batch04$, $batch04$Comparing the chameleon's retraction muscles with other animals' says nothing about why extension holds up in the cold.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT147-S4-Q1$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
